//! The environment: `carbine.atmosphere`.
//!
//! The register answers for the whole place rather than for one thing in it: what
//! time the clock says, how far you can see, what the sky looks like and what is
//! falling. Only the last of those is generated, and it is generated by the particle
//! generator - `atmosphere.new("rain")` is a short way of writing a crowd and hanging
//! it on the sky, so the handle it hands back is a `Particle` and every knob a
//! particle has is a knob on the weather.
//!
//! Fog is not a particle. It is the air itself, so it is a number on this register
//! and there is nothing to start or stop.

use pyo3::prelude::*;
use pyo3::types::PyAny;

use crate::math::{PyVec3, extract_vec3};
use crate::procedural::Particle;
use crate::sky::PySky;
use crate::with_scene;

/// The environment register, `carbine.atmosphere`.
#[pyclass(frozen, module = "carbine", name = "Atmosphere")]
pub struct PyAtmosphere;

impl PyAtmosphere {
    pub(crate) fn new() -> Self {
        Self
    }
}

#[pymethods]
impl PyAtmosphere {
    /// The backdrop and the one light the world is shaded by. It is the sky the
    /// clock moves the sun across, which is why it lives here.
    #[pyo3(name = "sky")]
    fn get_sky(&self) -> PySky {
        PySky::new()
    }

    /// Where the sun is, in hours past midnight. `atmosphere.time("07:30")` writes
    /// the clock the way a person reads one and `atmosphere.time(18)` writes it as
    /// a count of hours; either way the answer is the hours, and reading it is
    /// simply `atmosphere.time()`. A clock past midnight wraps round.
    #[pyo3(name = "time")]
    #[pyo3(signature = (clock = None))]
    fn set_time(&self, clock: Option<&Bound<'_, PyAny>>) -> PyResult<f32> {
        let Some(clock) = clock else {
            return with_scene(|scene| Ok(scene.time_of_day()));
        };

        if let Ok(text) = clock.extract::<String>() {
            with_scene(|scene| {
                scene.set_time_from_clock(&text)?;
                Ok(scene.time_of_day())
            })
        } else if let Ok(hours) = clock.extract::<f64>() {
            with_scene(|scene| {
                scene.set_time_of_day(hours as f32);
                Ok(scene.time_of_day())
            })
        } else {
            Err(pyo3::exceptions::PyTypeError::new_err(
                "a time is a clock like \"07:30\" or hours past midnight",
            ))
        }
    }

    /// How far the air lets you see, as a percent of the way from clear to a wall:
    /// 0 is a bright day and 100 is not seeing your own hand.
    #[getter]
    fn fog(&self) -> PyResult<f32> {
        with_scene(|scene| Ok(scene.atmosphere().fog))
    }

    #[setter]
    fn set_fog(&self, value: f64) -> PyResult<()> {
        with_scene(|scene| {
            scene.set_fog(value as f32);
            Ok(())
        })
    }

    /// The colour the distance is lost in.
    #[getter(fogColor)]
    fn fog_color(&self) -> PyResult<PyVec3> {
        let color = with_scene(|scene| Ok(scene.atmosphere().fog_color))?;
        Ok(PyVec3::plain(color))
    }

    /// A colour written the way an object colour is: `"#rrggbb"` and friends, or a
    /// `Vec3` and `(r, g, b)` tuple in 0..1.
    #[setter(fogColor)]
    fn set_fog_color(&self, value: Bound<'_, PyAny>) -> PyResult<()> {
        if let Ok(hex) = value.extract::<String>() {
            return with_scene(|scene| scene.set_fog_color_hex(&hex));
        }
        let color = extract_vec3(&value)?;
        with_scene(|scene| {
            scene.set_fog_color(color);
            Ok(())
        })
    }

    /// Writes one of the weathers the engine knows and hands back its handle, which
    /// is an ordinary particle system hung on the sky. `carbine.atmosphere.new("rain")`
    /// is the short way of asking for the crowd `procedural.particles()` would let you
    /// build by hand, so `shape`, `count` and the rest are all on the handle.
    #[pyo3(name = "new")]
    #[pyo3(signature = (kind, *, name = None))]
    fn create_precipitation(&self, kind: &str, name: Option<String>) -> PyResult<Particle> {
        let id = with_scene(|scene| scene.create_precipitation(kind, name))?;
        Ok(Particle::from_id(id))
    }

    /// The kinds `new()` accepts.
    #[pyo3(name = "kinds")]
    fn precipitation_kinds(&self) -> Vec<&'static str> {
        carbine_core::Precipitation::NAMES.to_vec()
    }

    /// The weather systems falling over the view right now, in the order they were
    /// written. A local crowd is not on the sky, so it is not the environment's
    /// business and does not appear here.
    fn running(&self) -> PyResult<Vec<Particle>> {
        let ids = with_scene(|scene| Ok(scene.precipitation_ids()))?;
        Ok(ids.into_iter().map(Particle::from_id).collect())
    }

    /// Switches every sky system off at once. Each one stays written and startable;
    /// this only clears the air, not the fog.
    #[pyo3(name = "stopAll")]
    fn stop_all(&self) -> PyResult<()> {
        with_scene(|scene| {
            scene.stop_all_precipitation();
            Ok(())
        })
    }

    fn __repr__(&self) -> PyResult<String> {
        let (time, fog) = with_scene(|scene| {
            let air = scene.atmosphere();
            Ok((air.time, air.fog))
        })?;
        Ok(format!("<Atmosphere air time={time} fog={fog}>"))
    }
}
